#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

typedef unsigned long long ULL;
typedef vector<bool> u128;
typedef long long ll;
const ll mod = 1000000007;

vector<ll> dp_prev, dp_cur;
vector<int> match_state;
vector<vector<int>> transition;
vector<u128> bfs_states;

ll modPow(ll base, ll exp) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int countBits(int x) {
    int cnt = 0;
    while (x) {
        cnt += x & 1;
        x >>= 1;
    }
    return cnt;
}

int getHash(const u128& state, int sz) {
    int pos = 0;
    for (size_t i = 0; i < state.size(); ++i) {
        pos = (pos * 2 + state[i]) % sz;
    }
    return pos;
}

u128 makeBit(int n) {
    u128 res(128, false);
    res[n] = true;
    return res;
}

int findOrInsert(u128 state, vector<u128>& hashTable, vector<int>& hashIndex, int& totalStates, int sz) {
    int pos = getHash(state, sz);
    while (true) {
        if (hashTable[pos] == state) {
            return hashIndex[pos];
        }
        if (hashTable[pos].empty()) {
            hashTable[pos] = state;
            bfs_states.push_back(state);
            hashIndex[pos] = totalStates;
            return totalStates++;
        }
        pos = (pos + 1) % sz;
    }
}

void precompute(int n) {
    int N = 1 << n;
    bfs_states.clear();
    bfs_states.push_back(u128(128, false));
    bfs_states[0][0] = true;

    vector<u128> fixedSize(n + 1, u128(128, false));
    for (int mask = 0; mask < N; ++mask) {
        int cnt = countBits(mask);
        fixedSize[cnt][mask] = true;
    }

    int hashTableSize = 0;
    if (n <= 6) {
        static const int sizes[] = {0, 5, 11, 37, 137, 821, 7529, 164184};
        hashTableSize = sizes[n];
    }

    vector<u128> hashTable(hashTableSize);
    vector<int> hashIndex(hashTableSize, -1);
    int totalStates = 1;

    vector<vector<int>> nextMask(N, vector<int>(1 << n, -1));
    match_state.resize(1 << n, 0);

    for (int k = 0; k < totalStates; ++k) {
        u128 state = bfs_states[k];
        vector<u128> predHall(n, u128(128, false));

        for (int mask = 0; mask < N; ++mask) {
            if (state[mask]) {
                for (int i = 0; i < n; ++i) {
                    predHall[i][mask | (1 << i)] = true;
                }
            }
        }

        for (int mask = 0; mask < N; ++mask) {
            u128 nextState = state;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    for (int j = 0; j < 128; ++j) {
                        if (predHall[i][j]) nextState[j] = true;
                    }
                }
            }
            nextMask[mask][k] = findOrInsert(nextState, hashTable, hashIndex, totalStates, hashTableSize);
        }

        for (int i = n; i >= 0; --i) {
            if ((state & fixedSize[i]).any()) {
                match_state[k] = i;
                break;
            }
        }
    }

    transition = nextMask;
    match_state.resize(totalStates);
}

ll computeExpectedMatching(int n, int m, vector<vector<ll>>& probMatrix) {
    int N = 1 << n;
    int totalStates = bfs_states.size();

    dp_prev.assign(totalStates, 0);
    dp_prev[0] = 1;

    for (int j = 0; j < m; ++j) {
        dp_cur.assign(totalStates, 0);

        for (int mask = 0; mask < N; ++mask) {
            ll probability = 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    probability = (probability * probMatrix[i][j]) % mod;
                } else {
                    probability = (probability * (mod - probMatrix[i][j])) % mod;
                }
            }

            for (int k = 0; k < totalStates; ++k) {
                int nextStateIndex = transition[mask][k];
                dp_cur[nextStateIndex] = (dp_cur[nextStateIndex] + probability * dp_prev[k]) % mod;
            }
        }

        dp_prev = dp_cur;
    }

    ll result = 0;
    for (int k = 0; k < totalStates; ++k) {
        if (match_state[k] == n) {
            result = (result + dp_prev[k]) % mod;
        }
    }
    return result;
}

int main() {
    int n, m;
    cin >> n;
    m = n;

    precompute(n);

    vector<vector<ll>> p(n, vector<ll>(m));
    ll inv100 = modPow(100, mod - 2);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            ll val;
            cin >> val;
            p[i][j] = (val * inv100) % mod;
        }
    }

    cout << computeExpectedMatching(n, m, p) << endl;

    return 0;
}
